INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'EK-1', 'even-keel-2026', 'reading.q08.org: render the italic lede on the piece page whenever the index shows it. renderPiece skips the lede when body_md starts with a heading, so the preview shows an italic lede that the page shows as plain text under a section heading. Fix: render p.lede italic and drop that first paragraph from the body; writer rule keeps the lede before the first heading', 'script', 'personal-companion/worker.js', 'planned', '2026-10-28: piece 2026-10-27-notes-73c73cae08c3e06f has no class=lede in its HTML; index uses p.lede, page uses !startsHeading guard (renderPiece, extractLede). Owner-reported. Verify live: class=lede present on that page after deploy' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'EK-1' AND source = 'even-keel-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'EK-2', 'even-keel-2026', 'Multi-source grounding for contested topics (policy, history, geopolitics, health, economics): require at least 3 independent sources spanning differing viewpoints and at least one non-US or non-Western source, instead of a single Wikipedia anchor', 'script', 'personal-companion/worker.js', 'planned', 'the 2026-10-27 Afghanistan piece cites Wikipedia only (War in Afghanistan, Afghanistan, 9/11 film); its balance comes from the writer prompt objection rule, not from source diversity' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'EK-2' AND source = 'even-keel-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'EK-3', 'even-keel-2026', 'Even-keel check in the fact-check stage: a separate model call scores each piece for one-sidedness (is the strongest opposing argument stated at full strength, are loaded terms avoided, are disputed claims attributed), failing pieces are revised or held; score logged per piece', 'script', 'personal-companion/worker.js', 'planned', 'no balance gate exists today; only grounding and numeric claim checks. Guard: pass rate must not fall below the existing fact-check pass rate' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'EK-3' AND source = 'even-keel-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'EK-4', 'even-keel-2026', 'Port the analysis form (structural reading, bargaining and incentive framing, strongest objection placed where the argument needs it, what-the-counting-leaves-out close) to q08 systems analyses for policy and science topics', 'script', 'q08-signal-engine/worker.js', 'planned', 'q08 today covers technology and infrastructure only; owner wants the form across disciplines from policy to science' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'EK-4' AND source = 'even-keel-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'EK-5', 'even-keel-2026', 'q08 publishing stall: signal engine published nothing in the last 3 runs and 57 h since the last piece; gate economics at 0.032 pass rate and 27.7x neuron overrun. Fix the gate so cost per published piece falls (cheaper first-pass model, earlier rejection) and publication resumes without raising any cap', 'script', 'q08-signal-engine/worker.js', 'planned', 'fleet.qnfo.org/api/managers 2026-10-28; q08.org latest post 2026-10-26. Verify live: new post on q08.org and publications_30d moves; guard: unified_cost_usd_30d not worse' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'EK-5' AND source = 'even-keel-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'EK-6', 'even-keel-2026', 'Portfolio-wide analysis-form library: one shared module (writer prompt, objection rule, even-keel check, sources footer, AI label) used by reading, q08, and the research pipeline, so a form improvement lands once', 'script', '_shared', 'planned', 'the form lives only inside personal-companion/worker.js today; q08 and research have separate writers' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'EK-6' AND source = 'even-keel-2026');
